head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[layer > M > showModal]<br/>모달 레이어를 표시하고, 지정된 컴포넌트를 제외한 모든 컴포넌트를 비활성화(disabled) 상태로 설정합니다.",
    "validation" : [
        "popupComponents(선택) 파라미터로 비활성화에서 제외할 컴포넌트 ID 배열을 설정할 수 있어야 합니다.",
        "popupComponents(선택) 파라미터에 포함된 컴포넌트는 모달 레이어 위에서 상호작용이 가능해야 합니다.",
        "popupComponents(선택) 파라미터 생략 시 모든 컴포넌트가 비활성화되어야 합니다.",
        "모달 레이어가 표시되면 Tab 키에 의한 포커스 이동도 차단되어야 합니다.",
        "이미 모달 레이어가 표시된 상태이면 중복 생성 없이 호출이 무시되어야 합니다.",
        "popupComponents 파라미터에 설정한 컴포넌트의 position 을 'relative' 로 적용하면 레이어 상위에 표시할 수 있어야 합니다.",
        "WebSquare.layer.hideModal() 호출 시 모달 레이어가 숨겨지고 컴포넌트가 원래 상태로 복원되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_showModal_onclick = function () {
    let excludeMode = par_excludeMode.getValue();

    if (excludeMode === 'all') {
        // 모든 컴포넌트 비활성화
        WebSquare.layer.showModal();
        wf_body_bottom.getObj("scwin").setReturnValue("showModal() 호출 (전체 비활성화)");
    } else if (excludeMode === 'exclude') {
        // btn_hideModal, wf_body_bottom 만 활성 유지
        WebSquare.layer.showModal(["btn_hideModal", "wf_body_bottom"]);
        wf_body_bottom.getObj("scwin").setReturnValue("showModal(['btn_hideModal', 'wf_body_bottom']) 호출");
        wf_body_bottom.getObj("scwin").setReturnValue("btn_hideModal, wf_body_bottom 만 활성 상태");
    }

    // 모달 상태 검증
    setTimeout(function () {
        let modalOverlay = document.querySelector(".w2modal");
        wf_body_bottom.getObj("scwin").setReturnValue("모달 레이어 존재 : " + (modalOverlay ? "PASS" : "FAIL"));
    }, 500);
}



scwin.btn_hideModal_onclick = function () {
    WebSquare.layer.hideModal();
    wf_body_bottom.getObj("scwin").setReturnValue("hideModal() 호출 → 모달 해제");

    setTimeout(function () {
        let modalOverlay = document.querySelector(".w2modal");
        wf_body_bottom.getObj("scwin").setReturnValue("모달 레이어 제거 : " + (!modalOverlay ? "PASS" : "FAIL"));
    }, 500);
}



scwin.btn_test_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("테스트 버튼 클릭됨 (모달 중이면 비활성화되어 클릭 불가)");
}



scwin.btn_focus_test_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("포커스 테스트 버튼 클릭됨 (모달 중이면 Tab 이동 및 클릭 불가)");
}
